from django.shortcuts import render
from django.http import HttpResponse
from django.contrib.auth.models import User
from django.core.paginator import Paginator, EmptyPage, PageNotAnInteger

def index(request):
    context = {'text': 'Welcome to our game'}
    return render(request, 'game/index.html', context)

def users(request):
	obj_list = User.objects.all().order_by("-date_joined")
	paginated_posts = Paginator(obj_list, 10)
	page = request.GET.get('page')
	try:
		posts = paginated_posts.page(page)
	except PageNotAnInteger:
		posts = paginated_posts.page(1)
	except EmptyPage:
		posts = paginated_posts.page(paginated_posts.num_pages)

	context = {'text': 'User list here', 'users': posts}
	return render(request, 'game/users.html', context)	

def user_detail(request, user_id):
	return HttpResponse("This page will have user details")

def leaderboard(request):
    context = {'text': 'Leaderboard goes here'}
    return render(request, 'game/leaderboard.html', context)

