import ast
import pep257

__version__ = '0.2.1.post1'


class pep257Checker(object):

    """flake8 needs a class to check python file."""

    name = 'flake8-pep257'
    version = __version__

    def __init__(self, tree, filename='(none)', builtins=None):
        self.tree = tree
        self.filename = filename

    def run(self):
        """Use directly check() api from pep257."""
        for error in pep257.check([self.filename]):
            # Ignore AllError, Environment error.
            if isinstance(error, pep257.Error):
                yield (error.line, 0, error.message, type(self))

# -*- coding: utf-8 -*-
"""flake8 plugin to check your docstrings with pep257.

Use it as a python module
"""
import io
import pep8
import pep257

__version__ = '0.3.0'


class Pep257Checker(object):
    """Adaptor for pep257 to be used within flake8."""

    name = 'pep257'
    version = __version__

    STDIN_SOURCES = set(['stdin', '-', '(none)', None])

    def __init__(self, tree, filename='(none)', builtins=None):
        self.tree = tree
        self.filename = filename

    @classmethod
    def init_from_config(cls, original_config):
        config = original_config._get_command_line_config()
        if 'pep257' in config:
            config = config['pep257']
        return cls(**config)

    def run(self):
        """Run the check."""
        if self.filename in self.STDIN_SOURCES:
            source = pep8.stdin_get_value(self.filename, self.tree)
            lines = source.splitlines()
            source = '\n'.join(lines)
            check_api = pep257.check_source
        else:
            check_api = pep257.check_file
        for error in check_api(source, self.filename):
            # Ignore AllError, Environment error.
            if isinstance(error, pep257.Error):
                yield (error.line, 0, error.message, type(self))
